 ident=r['url'].split('/')[-1].split('-')[0];src=r['file'];x=np.frombuffer(subprocess.check_output(['ffmpeg','-v','error','-i',src,'-f','f32le','-ac','2','-ar','44100','-']),dtype='<f4').reshape(-1,2)
